<script lang="ts">
  import type { DeviceSnapshot, PresenceState } from '../api/types';
  import { formatThroughput } from './networkFormat';
  import type { LiveState } from '../stores/live';
  let { liveState = null }: { liveState?: LiveState | null } = $props();
  let query = $state(''); let tab = $state('all' as 'all' | 'confirmed' | 'needs-confirm');
  const devices = $derived(liveState ? liveState.deviceOrder.map((id) => liveState.devices[id]).filter((device): device is DeviceSnapshot => Boolean(device)) : []);
  const visible = $derived(devices.filter((device) => {
    const text = `${device.owner_name ?? ''} ${device.identity.classification ?? ''} ${device.device_id}`.toLowerCase();
    const matchesTab = tab === 'all' || (tab === 'confirmed' ? device.owner_confirmed : !device.owner_confirmed);
    return matchesTab && text.includes(query.trim().toLowerCase());
  }));
  function confidence(device: DeviceSnapshot): string { if (device.owner_confirmed) return 'Confirmed'; if (device.evidence) return `${Math.round(device.evidence.confidence * 100)}% likely`; return 'Needs evidence'; }
  function presenceLabel(value: PresenceState): string { return value === 'unknown' ? 'Presence unavailable' : value; }
  function bytes(device: DeviceSnapshot): string { return formatThroughput(device.bandwidth.available ? (device.bandwidth.upload ?? 0) + (device.bandwidth.download ?? 0) : null); }
  function seen(value: string): string { return new Date(value).toLocaleString([], { dateStyle: 'medium', timeStyle: 'short' }); }
  </script>

<section class="devices-view" aria-labelledby="devices-heading"><div class="view-heading"><div><p class="kicker">DEVICES / IDENTITY</p><h1 id="devices-heading">Know what is home.</h1><p class="muted">Identity is earned from evidence, never guessed from a name alone.</p></div></div><label class="search"><span>Search devices</span><input type="search" bind:value={query} placeholder="e.g. living room TV" /></label><div class="tabs" role="group" aria-label="Filter devices">{#each [['all','All'],['confirmed','Confirmed'],['needs-confirm','Needs confirmation']] as item}<button class:active={tab === item[0]} onclick={() => tab = item[0] as typeof tab} type="button" aria-pressed={tab === item[0]}>{item[1]}</button>{/each}</div><p class="device-result-count" role="status">{visible.length} of {devices.length} devices{!liveState?.connected && devices.length ? ' · Last known data' : ''}</p>{#if visible.length === 0}<div class="empty-state device-empty"><span class="empty-icon">⌁</span><div><strong>{devices.length ? 'No devices match' : liveState?.connected ? 'No devices discovered yet' : 'Live device list unavailable'}</strong><p class="muted">{devices.length ? 'Try a different name or clear your filters.' : liveState?.connected ? 'Devices will appear when the collector discovers them.' : 'Check the local collector connection to load your devices.'}</p>{#if query || tab !== 'all'}<button class="reset-filters" type="button" onclick={() => { query = ''; tab = 'all'; }}>Clear filters</button>{/if}</div></div>{:else}<div class="device-table">{#each visible as device}<article class="device-card"><div class="device-name"><span class="device-symbol" aria-hidden="true">◌</span><div><strong>{device.owner_name ?? `Device ${device.device_id.slice(0, 8)}`}</strong><span>{device.identity.classification ?? 'Identity unavailable'} · {presenceLabel(device.presence.state)}</span></div></div><span class="confidence {device.owner_confirmed ? 'confirmed' : 'likely'}"><span aria-hidden="true">{device.owner_confirmed ? '✓' : '△'}</span> {confidence(device)}</span><p><b>Evidence</b>{device.evidence ? `${device.evidence.family} via ${device.evidence.source}` : 'Unavailable — no identity evidence'}</p><p><b>Throughput</b>{bytes(device)} · {device.bandwidth.coverage ?? 'coverage unavailable'}</p><p><b>First / last seen</b>{seen(device.first_seen_at)} → {seen(device.last_seen_at)}</p><p><b>Owner confirmation</b>{device.owner_confirmed ? 'Confirmed by you' : 'Needs your confirmation'}</p></article>{/each}</div>{/if}</section>
